families.make_source:
def make(n):
    limit = min(max(1, n), 8)
    return [[f"1.0.dev{'0'*i}"] for i in range(1, limit+1)]

def make(n):
    limit = min(max(1, n), 8)
    return [[f"{'0'*i}!1.0"] for i in range(1, limit+1)]

def make(n):
    limit = min(max(1, n), 8)
    # pattern: <epoch>!<release>a<pre>.post<post>.dev<dev>+<local>
    # increase the digit count of each numeric part with i
    return [
        [f"{'0'*i}!1.0a{'0'*i}.post{'0'*i}.dev{'0'*i}+{'x'*i}"]
        for i in range(1, limit+1)
    ]

def make(n):
    limit = min(max(1, n), 8)
    return [[f"{i}!1{a}.0{b}"] for i in range(1, limit + 1)]
